// The shared components and the typed settings forms (docs/55), on the plain server and the
// database e2e/console_server.py seeded for this run: the CSP trial of every converted screen
// (the tooltip is placed through the CSSOM, the dialogs are native: nothing may be blocked), the
// components by keyboard alone, each new state photographed and checked by axe in both themes,
// and every role's screens at a phone's width. The passwords were generated by
// playwright.config.ts.

import { expect, test, type Page } from "@playwright/test";
import { picturedAndChecked } from "./a11y";
import {
  ADMIN,
  ALL,
  APP_ADMIN,
  NOT_AVAILABLE,
  ORG_READER,
  Scan,
  logIn,
  sections,
  type Account,
} from "./session";

test.describe.configure({ mode: "serial" });

/** Every content-security-policy violation the page reports, gathered from its start. */
async function watchPolicy(page: Page): Promise<() => Promise<string[]>> {
  await page.addInitScript(() => {
    const seen: string[] = [];
    Object.assign(window, { policyViolations: seen });
    document.addEventListener("securitypolicyviolation", (event) => {
      seen.push(`${event.violatedDirective} ${event.blockedURI}`);
    });
  });
  return () =>
    page.evaluate(() => (window as unknown as { policyViolations: string[] }).policyViolations);
}

/** The application page's tabs these specs open, by the names the sidebar used to give them. */
const TABS: Record<string, [string, string]> = {
  "Application settings": ["settings", "Settings"],
  "Alert rules": ["rules", "Alert rules"],
  "API keys": ["keys", "API keys"],
};

async function open(page: Page, item: string, application?: string): Promise<void> {
  const tab = TABS[item];
  if (tab !== undefined) {
    // A tab of the application's page (docs/56), by its address as a link does.
    const id = /\(([^)]+)\)$/.exec(application ?? "")?.[1] ?? application ?? "app-one";
    await page.evaluate((hash) => {
      window.location.hash = hash;
    }, `#/app/${id}/${tab[0]}`);
    await expect(
      page
        .getByRole("navigation", { name: "Application sections" })
        .getByRole("link", { name: tab[1], exact: true }),
    ).toHaveAttribute("aria-current", "page");
    return;
  }
  await sections(page).getByRole("link", { name: item, exact: true }).click();
  // The screen opened, not the one before it (each screen's heading is its item's name).
  await expect(page.getByRole("heading", { name: item, level: 2, exact: true })).toBeVisible();
  if (application !== undefined) {
    await page
      .getByRole("combobox", { name: "Application", exact: true })
      .selectOption({ label: application });
  }
}

for (const who of [ADMIN, ORG_READER] as Account[]) {
  test(`CSP trial: ${who.username} on every converted screen blocks nothing`, async ({ page }) => {
    const violations = await watchPolicy(page);
    const requests: string[] = [];
    page.on("request", (request) => requests.push(request.url()));
    await page.goto("/dashboard/");
    await logIn(page, who);
    // The tooltip, opened by focus and placed through the CSSOM.
    await open(page, "Applications");
    await page
      .getByRole("button", { name: /too few to judge/i })
      .first()
      .focus();
    await expect(page.getByRole("tooltip").first()).toBeVisible();
    await open(page, "Organization settings");
    await expect(page.getByRole("region", { name: "Caps", exact: true })).toBeVisible();
    await open(page, "Application settings", "App one (app-one)");
    await expect(page.getByRole("region", { name: "History", exact: true })).toBeVisible();
    await open(page, "Alert rules", "App one (app-one)");
    await expect(page.getByRole("table", { name: "Rules" })).toBeVisible();
    await open(page, "Incidents");
    await page.getByRole("tab", { name: "resolved", exact: true }).click();
    if (who === ADMIN) {
      await open(page, "Channels");
      await expect(page.getByRole("region", { name: "Channel list", exact: true })).toBeVisible();
      await open(page, "API keys", "App one (app-one)");
      await page
        .getByRole("button", { name: /^Revoke / })
        .first()
        .click();
      await expect(page.getByRole("alertdialog", { name: "Revoke a key" })).toBeVisible();
      await page.keyboard.press("Escape");
      await expect(page.getByRole("alertdialog")).toHaveCount(0);
    }
    expect(await violations()).toEqual([]);
    const origin = new URL(page.url()).origin;
    expect(requests.filter((url) => !url.startsWith(origin) && !url.startsWith("data:"))).toEqual(
      [],
    );
  });
}

test("by keyboard alone: the typed form (switch, number, chips, Discard), tabs, a sort, a confirmation, a tooltip", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ADMIN);
  await open(page, "Application settings", "App two (app-two)");
  const edit = page.getByRole("region", { name: "Edit", exact: true });
  const changes = edit.getByRole("region", { name: "Changes", exact: true });

  // The switch: Space turns it.
  const toggle = edit.getByRole("switch", { name: "allow_downgrade_default", exact: true });
  const was = await toggle.isChecked();
  await toggle.focus();
  await page.keyboard.press("Space");
  await expect(toggle).toBeChecked({ checked: !was });
  await expect(changes).toContainText("allow_downgrade_default");

  // A number, typed.
  const number = edit.getByRole("spinbutton", { name: "chat_first_token_ms", exact: true });
  await number.focus();
  await page.keyboard.press("ControlOrMeta+a");
  await page.keyboard.type("20000");
  await expect(changes).toContainText("20000 ms");

  // A chip added with Enter, then removed from its own button with Enter.
  const add = edit.getByRole("textbox", { name: "Add to allowed_tiers", exact: true });
  await add.focus();
  await page.keyboard.type("e2e-tier");
  await page.keyboard.press("Enter");
  const remove = edit.getByRole("button", { name: "Remove e2e-tier from allowed_tiers" });
  await expect(remove).toBeVisible();
  await remove.focus();
  await page.keyboard.press("Enter");
  await expect(remove).toHaveCount(0);

  // The Save bar: Discard by keyboard puts everything back.
  const bar = page.getByRole("region", { name: "Save changes", exact: true });
  await expect(bar).toContainText("2 changes");
  await bar.getByRole("button", { name: "Discard" }).focus();
  await page.keyboard.press("Enter");
  await expect(bar).toHaveCount(0);
  await expect(toggle).toBeChecked({ checked: was });

  // Tabs: one in the Tab order, the arrows and End move and select.
  await open(page, "Incidents");
  const every = page.getByRole("tab", { name: "Every state", exact: true });
  await every.focus();
  await page.keyboard.press("ArrowRight");
  await expect(page.getByRole("tab", { name: "pending", exact: true })).toBeFocused();
  await expect(page.getByRole("tab", { name: "pending", exact: true })).toHaveAttribute(
    "aria-selected",
    "true",
  );
  await page.keyboard.press("End");
  await expect(page.getByRole("tab", { name: "resolved", exact: true })).toBeFocused();
  await page.keyboard.press("Home");
  await expect(every).toBeFocused();

  // A sortable header, by keyboard.
  await open(page, "Alert rules", "App one (app-one)");
  const header = page.getByRole("columnheader", { name: "Rule" });
  await header.getByRole("button", { name: "Rule" }).focus();
  await page.keyboard.press("Enter");
  await expect(header).toHaveAttribute("aria-sort", "ascending");
  await expect(page.getByText("Sorting applies to the rows on this page only.")).toBeVisible();

  // A confirmation: the focus starts on Cancel, Escape closes it and gives the focus back.
  await open(page, "API keys", "App one (app-one)");
  const revoke = page.getByRole("button", { name: /^Revoke / }).first();
  await revoke.focus();
  await page.keyboard.press("Enter");
  const dialog = page.getByRole("alertdialog", { name: "Revoke a key" });
  await expect(dialog.getByRole("button", { name: "Cancel" })).toBeFocused();
  await page.keyboard.press("Escape");
  await expect(dialog).toHaveCount(0);
  await expect(revoke).toBeFocused();

  // A tooltip opens on focus and closes on Escape.
  await open(page, "Applications");
  const dash = page.getByRole("button", { name: /too few to judge/i }).first();
  await dash.focus();
  const tip = page.getByRole("tooltip").first();
  await expect(tip).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(tip).toBeHidden();
  expect(await scan.leaks(page)).toEqual([]);
});

test("each new state, photographed and checked by axe in both themes", async ({
  page,
}, testInfo) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ADMIN);

  await open(page, "Application settings", "App two (app-two)");
  const edit = page.getByRole("region", { name: "Edit", exact: true });
  await edit.getByRole("spinbutton", { name: "chat_first_token_ms", exact: true }).fill("20000");
  await edit.getByRole("textbox", { name: "Add to allowed_tiers", exact: true }).fill("e2e-tier");
  await edit.getByRole("button", { name: "Add", exact: true }).first().click();
  await expect(page.getByRole("status", { name: "Check result" })).not.toContainText("Checking");
  await picturedAndChecked(page, testInfo, "ui-settings-form-changed");
  await edit.getByText("Advanced: edit as JSON").click();
  await picturedAndChecked(page, testInfo, "ui-settings-form-advanced");
  await page.getByRole("button", { name: "Discard" }).click();

  await open(page, "Organization settings");
  await expect(page.getByRole("region", { name: "Edit", exact: true })).toBeVisible();
  await picturedAndChecked(page, testInfo, "ui-organization-form");

  await open(page, "Incidents");
  await page.getByRole("tab", { name: "acknowledged", exact: true }).click();
  await picturedAndChecked(page, testInfo, "ui-incidents-tabs");

  await open(page, "Alert rules", "App one (app-one)");
  await page.getByRole("columnheader", { name: "Rule" }).getByRole("button").click();
  await picturedAndChecked(page, testInfo, "ui-rules-sorted");

  await open(page, "API keys", "App one (app-one)");
  await page
    .getByRole("button", { name: /^Revoke / })
    .first()
    .click();
  await expect(page.getByRole("alertdialog", { name: "Revoke a key" })).toBeVisible();
  await picturedAndChecked(page, testInfo, "ui-confirm-dialog");
  await page.getByRole("alertdialog").getByRole("button", { name: "Cancel" }).click();

  await open(page, "Channels");
  await picturedAndChecked(page, testInfo, "ui-channels");

  await open(page, "Applications");
  await page
    .getByRole("button", { name: /too few to judge/i })
    .first()
    .focus();
  await expect(page.getByRole("tooltip").first()).toBeVisible();
  await picturedAndChecked(page, testInfo, "ui-tooltip");
  expect(await scan.leaks(page)).toEqual([]);
});

/** The organization's screens each role may open, as the gateway's navigation draws them. */
const SCREENS = ["Applications", "Organization settings", "Channels", "Incidents"];

for (const who of ALL) {
  test(`a phone: ${who.username}'s screens at 390 px, both themes, under axe`, async ({
    page,
  }, testInfo) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto("/dashboard/");
    await logIn(page, who);
    const role = who.username.replace(/-e2e$/, "");
    await picturedAndChecked(page, testInfo, `phone-${role}-landing`);
    await page.getByRole("button", { name: "Open the navigation" }).click();
    const drawer = page.getByRole("dialog", { name: "Navigation" });
    const offered = await drawer.getByRole("link").allTextContents();
    await page.keyboard.press("Escape");
    const narrow = async (slug: string) => {
      // No page wider than the phone: wide tables scroll in their own box.
      expect(
        await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth),
      ).toBeLessThanOrEqual(0);
      await picturedAndChecked(page, testInfo, `phone-${role}-${slug}`);
    };
    // Each tab of App one's page the gateway allows it (docs/56).
    await page.evaluate(() => {
      window.location.hash = "#/app/app-one/overview";
    });
    const tabs = page.getByRole("navigation", { name: "Application sections" });
    // Its tabs, or the landing's sentence for a session the page is not open to.
    await expect(tabs.or(page.getByRole("alert").filter({ hasText: NOT_AVAILABLE }))).toBeVisible();
    if (await tabs.isVisible()) {
      for (const tab of await tabs.getByRole("link").allTextContents()) {
        await tabs.getByRole("link", { name: tab, exact: true }).click();
        await expect(tabs.getByRole("link", { name: tab, exact: true })).toHaveAttribute(
          "aria-current",
          "page",
        );
        await narrow(`app-${tab.toLowerCase().replaceAll(" ", "-")}`);
      }
    }
    for (const item of SCREENS) {
      if (!offered.includes(item)) continue;
      await page.getByRole("button", { name: "Open the navigation" }).click();
      await drawer.getByRole("link", { name: item, exact: true }).click();
      await expect(drawer).toBeHidden();
      await expect(page.getByRole("heading", { name: item, level: 2, exact: true })).toBeVisible();
      // No page wider than the phone: wide tables scroll in their own box.
      expect(
        await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth),
      ).toBeLessThanOrEqual(0);
      const slug = item.toLowerCase().replaceAll(" ", "-");
      await picturedAndChecked(page, testInfo, `phone-${role}-${slug}`);
    }
  });
}

test("an application's admin keeps its own application's typed form, and no organization form", async ({
  page,
}) => {
  await page.goto("/dashboard/");
  await logIn(page, APP_ADMIN);
  await open(page, "Application settings", "app-one");
  await expect(page.getByRole("region", { name: "Edit", exact: true })).toBeVisible();
  await expect(
    page.getByRole("switch", { name: "allow_downgrade_default", exact: true }),
  ).toBeVisible();
  await expect(sections(page).getByRole("link", { name: "Organization settings" })).toHaveCount(0);
});
